/**
 * Derives component composition from source and writes:
 *   app/gallery/composition.generated.ts   used by the gallery ("composes" / "used by")
 *   docs/frontend/component-catalogue.md   the reference list for developers
 * Also enforces the registry rule (UI-GOV-02): every component file has a registry entry and vice
 * versa. `--check` fails when the generated files are stale instead of writing them.
 */
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { categories, registry } from '../app/gallery/registry';

const root = fileURLToPath(new URL('..', import.meta.url));
const componentsDir = `${root}app/components/`;
const docsOut = fileURLToPath(
  new URL('../../../docs/frontend/component-catalogue.md', import.meta.url),
);
const tsOut = `${root}app/gallery/composition.generated.ts`;

const files = readdirSync(componentsDir)
  .filter((f) => f.endsWith('.vue'))
  .map((f) => f.replace('.vue', ''))
  .sort();
const names = new Set(files);

const problems: string[] = [];
for (const f of files)
  if (!registry.some((e) => e.name === f)) problems.push(`${f}.vue has no registry entry`);
for (const e of registry)
  if (!names.has(e.name)) problems.push(`registry entry ${e.name} has no component file`);
const dupes = registry.map((e) => e.name).filter((n, i, a) => a.indexOf(n) !== i);
for (const d of dupes) problems.push(`duplicate registry entry ${d}`);

const composes: Record<string, string[]> = {};
const usedBy: Record<string, string[]> = Object.fromEntries(files.map((f) => [f, []]));
for (const f of files) {
  const src = readFileSync(`${componentsDir}${f}.vue`, 'utf8');
  const deps = [...src.matchAll(/from '\.\/(Ui\w+)\.vue'/g)]
    .map((m) => m[1]!)
    .filter((d) => d !== f);
  composes[f] = [...new Set(deps)].sort();
  for (const d of composes[f]!) usedBy[d]?.push(f);
}

const ts = `/* GENERATED by scripts/build-catalogue.ts. Do not edit by hand. */
export const composition: Record<string, { composes: string[]; usedBy: string[] }> = ${JSON.stringify(
  Object.fromEntries(
    files.map((f) => [f, { composes: composes[f], usedBy: (usedBy[f] ?? []).sort() }]),
  ),
  null,
  2,
)};
`;

const md: string[] = [
  '# Component catalogue',
  '',
  '> Generated by `npm run catalogue:build -w @imp/ui` from `packages/ui/app/gallery/registry.ts` and the component sources. Do not edit by hand.',
  '> Browse every component, state and composition live at `/ui/components` (run `npm run dev -w @imp/web`).',
  '> **Before building a new component, search this list** (see `docs/frontend/README.md`, decision ADR-F002).',
  '',
  `${registry.length} components.`,
  '',
];
for (const cat of categories) {
  md.push(
    `## ${cat}`,
    '',
    '| Component | What it is for | Composes | Used by | Spec |',
    '|---|---|---|---|---|',
  );
  for (const e of registry.filter((r) => r.category === cat)) {
    const c = composes[e.name]?.map((n) => `\`${n}\``).join(', ') || '-';
    const u =
      usedBy[e.name]
        ?.sort()
        .map((n) => `\`${n}\``)
        .join(', ') || '-';
    md.push(`| \`${e.name}\` | ${e.summary} | ${c} | ${u} | ${e.specRefs.join(', ')} |`);
  }
  md.push('');
}
const reused = registry
  .map((e) => ({ name: e.name, n: usedBy[e.name]?.length ?? 0 }))
  .filter((r) => r.n > 0)
  .sort((a, b) => b.n - a.n)
  .slice(0, 8);
md.push(
  '## Most reused',
  '',
  ...reused.map((r) => `- \`${r.name}\`: used by ${r.n} components`),
  '',
);
const mdText = md.join('\n');

if (problems.length > 0) {
  console.error('FAIL: catalogue');
  for (const p of problems) console.error(`  - ${p}`);
  process.exit(1);
}

const out: Array<[string, string]> = [
  [tsOut, ts],
  [docsOut, mdText],
];
if (process.argv.includes('--check')) {
  const stale = out.filter(([p, c]) => !existsSync(p) || readFileSync(p, 'utf8') !== c);
  if (stale.length) {
    console.error(
      `FAIL: catalogue:check - stale: ${stale.map(([p]) => p).join(', ')}\nRun: npm run catalogue:build -w @imp/ui`,
    );
    process.exit(1);
  }
  console.warn(`OK: catalogue up to date (${registry.length} components)`);
} else {
  for (const [p, c] of out) writeFileSync(p, c);
  console.warn(`OK: catalogue generated (${registry.length} components)`);
}
